entries[46343] = { ["name"] = "Inbrunst des Protektorats", ["text"] = "Wird beim Aufheben gebunden\nHals\n345 Rüstung\n+49 Stärke\n+94 Ausdauer\nBenötigt Stufe 80\nAnlegen: Erhöht Eure Parierwertung um 62.\nAnlegen: Erhöht Eure Waffenkundewertung um 32." }
entries[46344] = { ["name"] = "Eisschermantel", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n239 Rüstung\n+66 Ausdauer\n+59 Intelligenz\n+58 Willenskraft\nHaltbarkeit 60 / 60\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 50.\nAnlegen: Erhöht die Zaubermacht um 97." }
entries[46345] = { ["name"] = "Armschienen der gerechten Reformation", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Platte\n1043 Rüstung\n+56 Ausdauer\n+46 Intelligenz\n\nBlauer Sockel\nSockelbonus: +4 Intelligenz\n\nHaltbarkeit 55 / 55\nBenötigt Stufe 80\nAnlegen: Erhöht die Tempowertung um 31.\nAnlegen: Stellt alle 5 Sek. 24 Mana wieder her.\nAnlegen: Erhöht die Zaubermacht um 55." }
entries[46346] = { ["name"] = "Stiefel der unruhigen Beute", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n917 Rüstung\n+60 Beweglichkeit\n+67 Ausdauer\n+44 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 49.\nAnlegen: Erhöht die Angriffskraft um 167.\nAnlegen: Erhöht den Rüstungsdurchschlag um 43." }
entries[46347] = { ["name"] = "Umhang der schlummernden Flamme", ["text"] = "Wird beim Aufheben gebunden\nRücken\n159 Rüstung\n+72 Ausdauer\n+32 Intelligenz\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 31.\nAnlegen: Stellt alle 5 Sek. 25 Mana wieder her.\nAnlegen: Erhöht die Zaubermacht um 73." }
entries[46348] = { ["name"] = "Formel: Waffe - Blutsauger", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch, eine Waffe dauerhaft so zu verzaubern, dass gelegentlich Blutreserve ausgelöst wird, wenn Ihr einen Feind schlagt oder Blutungsschaden verursacht. Dadurch werdet Ihr bei niedriger Gesundheit geheilt. Verzauberung benötigt Stufe 75.\nEine Waffe dauerhaft so verzaubern, dass sie gelegentlich bei einem erzielten Treffer oder dem Verursachen von Blutungseffekten den Effekt 'Blutreserve' gewährt. Wenn Eure Gesundheit unter 35% sinkt, stellt die Blutreserve 360 to 440 Gesundheit wieder her. Hält 20 sec lang an und ist 5-mal stapelbar.\n\nUm diese Verzauberung nutzen zu können, muss der Träger mindestens Stufe 75 erreicht haben." }
entries[46349] = { ["name"] = "Kochmütze", ["text"] = "Wird beim Aufheben gebunden\nKopf\nAnlegen: Gestattet es Euch, schneller zu kochen." }
entries[46350] = { ["name"] = "Säule der Seelenstärke", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n313 - 571 Schaden Tempo 2.90\n(152.41 Schaden pro Sekunde)\n+168 Ausdauer\n+112 Intelligenz\n+86 Willenskraft\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nErhöht die Angriffskraft um 1366 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die kritische Trefferwertung um 56.\nAnlegen: Erhöht die Zaubermacht um 515." }
entries[46351] = { ["name"] = "Blutzermalmerknüppel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n178 - 332 Schaden Tempo 1.50\n(170.00 Schaden pro Sekunde)\n+49 Beweglichkeit\n+41 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 80\nErhöht die Angriffskraft um 1612 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die kritische Trefferwertung um 50.\nAnlegen: Erhöht die Angriffskraft um 78.\nAnlegen: Erhöht Eure Waffenkundewertung um 26." }
