entries[46398] = { ["name"] = "Dreifarbige Katze", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure Katze beschwören und freigeben." }
entries[46399] = { ["name"] = "Donnerschädel", ["text"] = "Benötigt Stufe 75\nBenötigt Braufest\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 19200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Trinken verbringt, werdet Ihr satt und erhaltet 1 hour lang 40 Ausdauer und Abhärtungswertung. Normaler Alkohol." }
