entries[46544] = { ["name"] = "Neugieriger Wolvarwelpe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man diesen Begleiter beschwört.\nMit Rechtsklick einen neugierigen Wolvarwelpen beschwören und freigeben." }
entries[46545] = { ["name"] = "Neugieriges Orakeljunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein neugieriges Gorlocjunges beschwören und freigeben." }
entries[46690] = { ["name"] = "Zuckerschädel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 18 sec insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[46691] = { ["name"] = "Totenspeise", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 24 sec pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Ausdauer und Willenskraft wird 15 min lang erhöht." }
entries[46693] = { ["name"] = "Kleiner Papierzeppelin", ["text"] = "Questgegenstand\nBenutzen: Wirft den Zeppelin Eurem Waisen aus Nordend zu. (15 Sek. Abklingzeit)\n\"Genau die richtige Größe für ein kleines Kind.\"" }
entries[46707] = { ["name"] = "Kleiner rosafarbener Dickhäuter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein kleinen rosafarbenen Dickhäuter beschwören und freigeben." }
entries[46708] = { ["name"] = "Frostwyrm des tödlichen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (300)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein extrem schnelles Reittier.\nBeschwört einen reitbaren Frostwyrm des tödlichen Gladiators oder gibt ihn frei. Das ist ein extrem schnelles Reittier." }
entries[46710] = { ["name"] = "Rezept: Totenspeise", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenötigt Tag der Toten\nBenutzen: Lehrt Euch, wie man Totenspeise backt.\nTotenspeise\nWird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Stellt im Verlauf von 24 sec pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Ausdauer und Willenskraft wird 15 min lang erhöht.\nBenötigt Herkömmliches Mehl , Eiskalte Milch" }
entries[46711] = { ["name"] = "Seelenkerze", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Platziert eine Seelenkerze, welche die Willenskraft aller in der Nähe um 4 erhöht. (5 Min Abklingzeit)" }
entries[46718] = { ["name"] = "Orangefarbene Ringelblumen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Tag der Toten\nBenutzen: Gewährt 30 sec lang Entdeckung geringer Unsichtbarkeit. Wirkt nur am Tag der Toten. (30 Sek. Abklingzeit)\n\"Zieht angeblich Geister an und hilft dabei, am Tag der Toten mit den Seelen der Verstorbenen zu kommunizieren.\"" }
entries[46723] = { ["name"] = "Pilgerhut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf" }
entries[46725] = { ["name"] = "Rotes Erbsengewehr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Feuert eine (größtenteils) harmlose Trockenerbse ab.\n200 Aufladungen\n\"Das einzig wahre Luftdruckgewehr mit 200 Schuss Erbsenmunition, in roter Sonderedition!\"" }
entries[46735] = { ["name"] = "Synthebräubrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKopf\nBenötigt Braufest\nAnlegen: Diese Brille simuliert die Effekte von Alkohol. Die Effekte können leicht entfernt werden, indem man die Brille absetzt.\n\"Die Brille, sie tut irgendetwas!\"" }
