entries[46803] = { ["name"] = "Rezept: Gewürzbrotfüllung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\n\nGewürzbrotfüllung\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Trefferwertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Gewürzbrot , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[46804] = { ["name"] = "Rezept: Kürbiskuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man Kürbiskuchen zubereitet.\n\nKürbiskuchen\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Reifer Tirisfalkürbis , Honig", ["unresolvedValues"] = true }
entries[46805] = { ["name"] = "Rezept: Moosbeerenchutney", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (160)\nBenutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\n\nMoosbeerenchutney\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Zaubermacht um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Säuerliche Moosbeeren vom Südstrom , Honig", ["unresolvedValues"] = true }
entries[46806] = { ["name"] = "Rezept: Kandierte Süßkartoffel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (220)\nBenutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\n\nKandierte Süßkartoffel\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Tempowertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Süßkartoffel aus Mulgore , Honig , Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[46807] = { ["name"] = "Rezept: Langsam gerösteter Truthahn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\nBenutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\n\nLangsam gerösteter Truthahn\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Angriffskraft um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze", ["unresolvedValues"] = true }
