entries[46847] = { ["name"] = "Zephyriumbomben", ["text"] = "Insel der Eroberung\nEinzigartig\nBenötigt Stufe 70\nBenutzen: Platziert eine Zephyriumbombe, die nach 10 Sekunden explodiert.\nZephyriumbomben werden beim Tod entfernt." }
