entries[46852] = { ["name"] = "Munitionsmanufaktur H17", ["text"] = "Benötigt Stufe 80\nBenutzen: Erzeugt 1000 auf Eure ausgerüstete Distanzwaffe abgestimmte Kugeln oder Pfeile.\n30 Aufladungen\n\"Um das geistige Eigentum des goblinschen Ingenieurshandwerks zu sichern, werden Manipulationen an der Munitionsmanufaktur zu ihrer Explosion führen. Vielen Dank.\"" }
